diff --git a/ets2panda/checker/ETSAnalyzer.cpp b/ets2panda/checker/ETSAnalyzer.cpp
index 3ff844151..02c2376e6 100644
--- a/ets2panda/checker/ETSAnalyzer.cpp
+++ b/ets2panda/checker/ETSAnalyzer.cpp
@@ -2982,6 +2982,17 @@ static Type *HandleNonMethodAndCallSite(ETSChecker *checker, ir::Expression *use
         if (parent->IsOverloadDeclaration()) {
             return type;
         }
+        if (parent->IsAssignmentExpression() && parent->AsAssignmentExpression()->Left() == expr) {
+            return type;
+        }
+    }
+
+    ES2PANDA_ASSERT(type->IsETSMethodType());
+    const auto *funcType = type->AsETSFunctionType();
+    for (auto *sig : funcType->CallSignatures()) {
+        if (sig->Function() != nullptr && sig->Function()->IsGetter()) {
+            return sig->ReturnType();
+        }
     }

     return nullptr;
diff --git a/ets2panda/checker/ETSAnalyzerHelpers.cpp b/ets2panda/checker/ETSAnalyzerHelpers.cpp
index 6279e8089..b9d1a327a 100644
--- a/ets2panda/checker/ETSAnalyzerHelpers.cpp
+++ b/ets2panda/checker/ETSAnalyzerHelpers.cpp
@@ -391,7 +391,13 @@ checker::Signature *ResolveCallExtensionFunction(checker::Type *functionType, ch
         // function call.
         auto *memberExpr = expr->Callee()->AsMemberExpression();
         expr->Arguments().insert(expr->Arguments().begin(), memberExpr->Object());
-        auto *signature = checker->FirstMatchSignatures(signatures, expr);
+        ArenaVector<Signature *> extSignatures(checker->ProgramAllocator()->Adapter());
+        for (auto *sig : signatures) {
+            if (sig->HasSignatureFlag(checker::SignatureFlags::EXTENSION_FUNCTION)) {
+                extSignatures.push_back(sig);
+            }
+        }
+        auto *signature = checker->FirstMatchSignatures(extSignatures, expr);
         if (signature == nullptr) {
             expr->Arguments().erase(expr->Arguments().begin());
             return nullptr;
diff --git a/ets2panda/checker/types/ets/etsFunctionType.cpp b/ets2panda/checker/types/ets/etsFunctionType.cpp
index 55dce536c..f5776c811 100644
--- a/ets2panda/checker/types/ets/etsFunctionType.cpp
+++ b/ets2panda/checker/types/ets/etsFunctionType.cpp
@@ -162,6 +162,9 @@ void ETSFunctionType::AddCallSignature(Signature *signature)
     } else if (signature->Function()->IsSetter()) {
         AddTypeFlag(TypeFlag::SETTER);
     }
+
+    hasExtensionSignatures_ |= signature->IsExtensionFunction() || signature->IsExtensionAccessor();
+    hasExtensionAccessorSignatures_ |= signature->IsExtensionAccessor();
     callSignatures_.push_back(signature);
 }

